@startuml

class Cinema {
  + Name : string
  + Town : string
}

class Theatre {
  + Number : int
}

class Show {
  + StartTime : datetime
  + EndTime : datetime
  + publish()
  + cancelShow()
}

class Movie {
  + Title : string
}

class MovieCopy {
  + Id : int
}

class CopyLocation {
  + Id : int
}

class Seat {
  + SeatNumber : int
}

class OnlineReservation {
  + ReservationTime : datetime
  + cancelReservation()
  + payWithCreditCard()
}

class AlternativeOffer {
  + expire()
  + accept()
  + decline()
}

class Ticket {
  + TicketId : int
  + SeatNumber : int
}

class Customer {
  + Name : string
}

Cinema "1" -- "*" Theatre
Cinema "1" -- "*" CopyLocation
Movie "1" -- "*" MovieCopy
MovieCopy "1" -- "*" CopyLocation
Theatre "1" -- "*" Show
CopyLocation "1" -- "*" Show
Show "1" -- "*" OnlineReservation
Show "1" -- "*" Ticket
Seat "1" -- "*" OnlineReservation
Seat "1" -- "*" Ticket
OnlineReservation "1" -- "0..1" AlternativeOffer
Customer "1" -- "*" OnlineReservation
Customer "1" -- "0..1" Ticket

@enduml

